    public void ShowSettingsPage(string name){
        CurrentSettingsPage=name;foreach(var entry in navigation){entry.Value.Background=entry.Key==name?new SolidColorBrush(Color.FromRgb(130,193,234)):Brushes.Transparent;entry.Value.Foreground=entry.Key==name?Ui.Ink:Ui.Accent;}
        if(name=="主页"){pageBody.Content=homeView;return;}
        StackPanel panel;
        switch(name){case "颜色和外观":panel=AppearancePage();break;case "桌面页面":panel=PagesPage();break;case "文件夹映射":panel=PortalsPage();break;case "卷起桌面分区":panel=RollPage();break;case "快速隐藏":panel=HidePage();break;case "布局和快照":panel=LayoutsPage();break;case "排序和组织":panel=RulesPage();break;case "AI 推荐":panel=AiPage();break;case "忽略文件":panel=IgnorePage();break;case "AI 工作目录":panel=WorkPage();break;case "MCP 连接":panel=McpPage();break;case "插件与组件":panel=PluginsPage();break;case "文件搜索":panel=SearchPage();break;case "最近文件":panel=RecentPage();break;case "截图与图像":panel=ScreenshotsPage();break;case "使用教程":panel=TutorialPage();break;default:panel=AboutPage();break;}
        pageBody.Content=new ScrollViewer(){Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};
    }
