    void AddColorSliders(Panel panel,TextBox color){
        var hue=Range(panel,"颜色（色相）",0,360,0);var saturation=Range(panel,"饱和度",0,1,0);bool updating=false;double value=1;
        Action read=delegate{try{var rgb=(Color)ColorConverter.ConvertFromString(color.Text);updating=true;double r=rgb.R/255.0,g=rgb.G/255.0,b=rgb.B/255.0,max=Math.Max(r,Math.Max(g,b)),min=Math.Min(r,Math.Min(g,b)),delta=max-min;value=max;double h=delta==0?0:max==r?60*((g-b)/delta%6):max==g?60*((b-r)/delta+2):60*((r-g)/delta+4);hue.Value=h<0?h+360:h;saturation.Value=max==0?0:delta/max;}catch{}finally{updating=false;}};
        Action write=delegate{if(updating)return;updating=true;double h=hue.Value/60,c=value*saturation.Value,x=c*(1-Math.Abs(h%2-1)),m=value-c,r=0,g=0,b=0;if(h<1){r=c;g=x;}else if(h<2){r=x;g=c;}else if(h<3){g=c;b=x;}else if(h<4){g=x;b=c;}else if(h<5){r=x;b=c;}else{r=c;b=x;}color.Text="#"+((byte)Math.Round((r+m)*255)).ToString("X2")+((byte)Math.Round((g+m)*255)).ToString("X2")+((byte)Math.Round((b+m)*255)).ToString("X2");updating=false;};read();hue.ValueChanged+=delegate{write();};saturation.ValueChanged+=delegate{write();};color.TextChanged+=delegate{if(!updating)read();};
    }
