    StackPanel HidePage(){
        var p=SettingsPage("桌面快速隐藏","双击桌面空白处隐藏 / 恢复分组，也可以使用 Ctrl+Alt+D。");var data=controller.Store.Data;Section(p,"设置");doubleClick=Option(p,"启用桌面空白处双击隐藏",data.DoubleClickHide,delegate(bool value){data.DoubleClickHide=value;SaveSettings(false);});Option(p,"隐藏 Windows 原生桌面图标（避免与分区重叠）",data.HideDesktopIcons,delegate(bool value){data.HideDesktopIcons=value;SaveSettings(false);controller.UpdateDesktopIntegration();});Option(p,"原生图标自动避开分区和插件（移到空位）",data.PushIconsAside,delegate(bool value){data.PushIconsAside=value;SaveSettings(false);controller.ScheduleIconPush();});p.Children.Add(Ui.Text("开启“隐藏原生桌面图标”后，桌面不再显示散落图标；关闭后原生图标恢复显示，并可让图标自动避开分区/插件。",12,Ui.Muted));
        var idle=Choice(p,"离开桌面后自动隐藏",new[]{"关闭","30 秒","60 秒","180 秒"},data.IdleHideSeconds==30?1:data.IdleHideSeconds==60?2:data.IdleHideSeconds==180?3:0);idle.SelectionChanged+=delegate{data.IdleHideSeconds=new[]{0,30,60,180}[idle.SelectedIndex];SaveSettings(false);};Option(p,"重新使用桌面时恢复自动隐藏的分组",data.AutoShowOnDesktop,delegate(bool value){data.AutoShowOnDesktop=value;SaveSettings(false);});p.Children.Add(Ui.Button("立即隐藏 / 恢复",controller.ToggleHidden));Section(p,"隐藏时保留的分组");foreach(var group in data.Groups){var g=group;Option(p,g.Name,g.ExcludeFromHide,delegate(bool value){g.ExcludeFromHide=value;SaveSettings(true);});}return p;
    }
    StackPanel LayoutsPage(){
        var p=SettingsPage("布局功能和快照","保存布局，调整对齐方式，以及屏幕工作区变化时的处理方式。");var data=controller.Store.Data;Section(p,"布局自动调整");var mode=Choice(p,"显示器工作区变化时",new[]{"保持位置","按工作区缩放","按显示器恢复"},data.LayoutMode=="按工作区缩放"?1:data.LayoutMode=="按显示器恢复"?2:0);mode.SelectionChanged+=delegate{data.LayoutMode=Convert.ToString(mode.SelectedItem);SaveSettings(false);};p.Children.Add(Ui.Text("屏幕外的标题始终会恢复到可触及的位置。按显示器恢复会记录不同工作区组合的分组位置。不同 DPI 与真实 Explorer 重启仍需实测。",12,Ui.Muted));
        Section(p,"对齐和间距");Option(p,"移动和缩放后对齐网格及邻近分组",data.SnapEnabled,delegate(bool value){data.SnapEnabled=value;SaveSettings(false);});var grid=Ui.Input(data.SnapGrid.ToString());var gap=Ui.Input(data.SnapGap.ToString());p.Children.Add(Ui.Text("网格大小（1–64）",12,Ui.Muted));p.Children.Add(grid);p.Children.Add(Ui.Text("分组间距（0–80）",12,Ui.Muted));p.Children.Add(gap);p.Children.Add(Ui.Button("保存对齐设置",delegate{int size,space;if(!Int32.TryParse(grid.Text,out size)||size<1||size>64||!Int32.TryParse(gap.Text,out space)||space<0||space>80){Ui.Info("请填写有效的网格大小和间距。",this);return;}data.SnapGrid=size;data.SnapGap=space;SaveSettings(false);}));p.Children.Add(Ui.Text("移动或缩放时按住 Shift，可暂时跳过对齐。",12,Ui.Muted));
        var adjustment=new StackPanel();while(p.Children.Count>2){UIElement child=p.Children[2];p.Children.RemoveAt(2);adjustment.Children.Add(child);}p.Children.Add(new Expander(){Header="对齐与显示器调整",Content=adjustment,IsExpanded=false,Margin=new Thickness(0,10,0,4)});Section(p,"布局快照");Option(p,"每天自动保存布局（保留最近 3 次自动快照）",data.AutoDailySnapshot,delegate(bool value){data.AutoDailySnapshot=value;controller.Store.DailySnapshot(DateTime.Today);SaveSettings(false);});p.Children.Add(Ui.Button("保存当前布局快照",delegate{controller.Store.Snapshot();ShowSettingsPage("布局和快照");SetStatus("布局快照已保存。");}));foreach(string path in Directory.GetFiles(controller.Store.SnapshotRoot,"*.json").OrderByDescending(SnapshotPreview.Date).Take(12)){p.Children.Add(SnapshotCard(path));}p.Children.Add(Ui.Button("导入 Fences 布局",Import));p.Children.Add(Ui.Button("撤销上一次更改",delegate{if(controller.Store.Undo()){SaveSettings(true);ShowSettingsPage("布局和快照");}}));return p;
    }
    StackPanel RulesPage(){var p=SettingsPage("新图标放置和自动组织","新增文件默认留在 Windows 桌面；按规则整理后进入分区。可设置每个分区的排序。");var data=controller.Store.Data;Option(p,"以后自动归类新出现的桌面文件",data.AutoRules,delegate(bool value){data.AutoRules=value;SaveSettings(false);});var actions=new WrapPanel();actions.Children.Add(Ui.Button("添加规则",delegate{RuleEditor(this);ShowSettingsPage("排序和组织");}));actions.Children.Add(Ui.Button("整理散落图标",controller.ApplyRules));actions.Children.Add(Ui.Button("预览分类建议",delegate{ShowSuggestions(controller.Store.Suggest(),"规则分类建议");}));p.Children.Add(actions);Section(p,"分区内排序");foreach(var group in data.Groups.Where(g=>String.IsNullOrEmpty(g.Folder))){var current=group;var row=new StackPanel(){Margin=new Thickness(0,0,0,12)};var choices=new[]{"名称","类型","修改时间","大小"};var sort=Choice(row,current.Name+" 排序方式",choices,Array.IndexOf(choices,current.Sort));var descending=Option(row,"倒序",current.SortDescending,delegate(bool value){current.SortDescending=value;SaveSettings(true);});sort.SelectionChanged+=delegate{if(sort.SelectedItem==null)return;current.Sort=Convert.ToString(sort.SelectedItem);SaveSettings(true);};p.Children.Add(row);}Section(p,"规则优先级");for(int i=0;i<data.Rules.Count;i++){int index=i;var rule=data.Rules[i];var row=new StackPanel(){Margin=new Thickness(0,0,0,12)};Option(row,rule.Name,rule.Enabled,delegate(bool value){rule.Enabled=value;SaveSettings(false);});var target=data.Groups.FirstOrDefault(g=>g.Id==rule.GroupId);row.Children.Add(Ui.Text(rule.Kind+" · "+rule.Extensions+" · 名称"+rule.NameMode+" "+rule.Contains+" → "+(target==null?"目标已移除":target.Name),12,Ui.Muted));var buttons=new WrapPanel();if(i>0)buttons.Children.Add(Ui.Button("上移",delegate{controller.Store.Checkpoint();data.Rules.RemoveAt(index);data.Rules.Insert(index-1,rule);SaveSettings(false);ShowSettingsPage("排序和组织");}));buttons.Children.Add(Ui.Button("移除规则",delegate{controller.Store.Checkpoint();data.Rules.Remove(rule);SaveSettings(false);ShowSettingsPage("排序和组织");}));row.Children.Add(buttons);p.Children.Add(row);}return p;}
    StackPanel AiPage(){var p=SettingsPage("AI 分类推荐","预览分类理由，勾选后再应用；每次整理可以撤销。");p.Children.Add(Ui.Button("请求 AI 建议",GetAi));p.Children.Add(Ui.Button("模型设置",AiSettings));p.Children.Add(Ui.Button("查看规则建议",delegate{ShowSuggestions(controller.Store.Suggest(),"规则分类建议");}));p.Children.Add(Ui.Text("支持本地 Ollama 和兼容 Chat Completions 的服务，仅发送文件名、扩展名与分组名称。",13,Ui.Muted));return p;}
    StackPanel AboutPage(){var p=SettingsPage("关于栖桌","独立实现的桌面整理软件 · 核心预览版 0.7.1");p.Children.Add(Ui.Text("已整理的桌面图标优先使用可恢复的隐藏属性；权限不足的快捷方式移入栖桌整理目录，并记录原位置。拖出分区时移回桌面。",13,Ui.Ink));Section(p,"配置与恢复");p.Children.Add(Ui.Text("配置自动保存，可通过下方按钮打开。",12,Ui.Muted));p.Children.Add(Ui.Button("打开配置目录",delegate{Shell.Open(controller.Store.Root);}));Section(p,"开源图标");p.Children.Add(Ui.Text("Fluent UI System Icons · Microsoft · MIT；素材与许可随程序源码提供。",13,Ui.Muted));return p;}
    public void CreateSelectedGroup(Rect bounds,bool folder,bool askName){
        string path="",name="新分组";
        if(folder){using(var browser=new System.Windows.Forms.FolderBrowserDialog()){browser.Description="选择要映射到所选区域的文件夹";if(browser.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;path=browser.SelectedPath;name=Path.GetFileName(path);if(String.IsNullOrEmpty(name))name=path;}}
        else if(askName){name=Ui.Ask("创建桌面分组","分组名称","新分组",this);if(String.IsNullOrWhiteSpace(name))return;}
        else {int count=2;while(controller.Store.Data.Groups.Any(g=>g.Name==name))name="新分组 "+count++;}
        if(controller.Running&&controller.Hidden)controller.ToggleHidden();controller.CreateAt(bounds,name,path);if(!controller.Running)controller.Start(true);SetStatus("已在所选区域创建"+(folder?"文件夹映射":"桌面分组")+"。");
    }
    void DrawGroup(){var overlay=new SelectionOverlay(this);overlay.Selected+=delegate(Rect bounds,bool folder){CreateSelectedGroup(bounds,folder,true);};overlay.Show();}
}
